INSERT INTO `chatbot_huan_luyen` (`id`, `y_dinh`, `cau_hoi`, `phan_hoi`, `trang_thai`, `thoi_gian_tao`) VALUES
(1, 'greeting', 'Xin chào', 'Xin chào! Mình có thể tư vấn cấu hình, tìm sản phẩm đang bán hoặc hỗ trợ đơn hàng.', 1, '2026-10-22 22:35:47'),
(2, 'greeting', 'Chào shop', 'Xin chào! Mình có thể tư vấn cấu hình, tìm sản phẩm đang bán hoặc hỗ trợ đơn hàng.', 1, '2026-10-22 22:35:47'),
(3, 'greeting', 'Có ai hỗ trợ không?', 'Xin chào! Mình có thể tư vấn cấu hình, tìm sản phẩm đang bán hoặc hỗ trợ đơn hàng.', 1, '2026-10-22 22:35:47'),
(4, 'greeting', 'Tôi cần tư vấn', 'Xin chào! Mình có thể tư vấn cấu hình, tìm sản phẩm đang bán hoặc hỗ trợ đơn hàng.', 1, '2026-10-22 22:35:47'),
(5, 'greeting', 'Bắt đầu hỗ trợ giúp tôi', 'Xin chào! Mình có thể tư vấn cấu hình, tìm sản phẩm đang bán hoặc hỗ trợ đơn hàng.', 1, '2026-10-22 22:35:47'),
(6, 'payment', 'Thanh toán bằng cách nào?', 'Chủ đề: thanh toán. Bạn có thể chọn thanh toán khi nhận hàng hoặc chuyển khoản mô phỏng lúc đặt hàng. Chuyển khoản trong phiên bản này chưa kết nối ngân hàng.', 1, '2026-10-22 22:35:47'),
(7, 'payment', 'Shop có nhận tiền mặt không?', 'Chủ đề: thanh toán. Bạn có thể chọn thanh toán khi nhận hàng hoặc chuyển khoản mô phỏng lúc đặt hàng. Chuyển khoản trong phiên bản này chưa kết nối ngân hàng.', 1, '2026-10-22 22:35:47'),
(8, 'payment', 'Có thể trả tiền khi nhận hàng không?', 'Chủ đề: thanh toán. Bạn có thể chọn thanh toán khi nhận hàng hoặc chuyển khoản mô phỏng lúc đặt hàng. Chuyển khoản trong phiên bản này chưa kết nối ngân hàng.', 1, '2026-10-22 22:35:47'),
(9, 'payment', 'Chuyển khoản có hoạt động không?', 'Chủ đề: thanh toán. Bạn có thể chọn thanh toán khi nhận hàng hoặc chuyển khoản mô phỏng lúc đặt hàng. Chuyển khoản trong phiên bản này chưa kết nối ngân hàng.', 1, '2026-10-22 22:35:47'),
(10, 'payment', 'Tôi có thể thanh toán online không?', 'Chủ đề: thanh toán. Bạn có thể chọn thanh toán khi nhận hàng hoặc chuyển khoản mô phỏng lúc đặt hàng. Chuyển khoản trong phiên bản này chưa kết nối ngân hàng.', 1, '2026-10-22 22:35:47'),
(11, 'checkout', 'Làm sao để đặt hàng?', 'Chủ đề: đặt hàng. Bạn chọn sản phẩm, thêm vào giỏ, đăng nhập rồi điền thông tin giao hàng để đặt hàng. Hiện cửa hàng hỗ trợ thanh toán khi nhận hàng hoặc chuyển khoản mô phỏng.', 1, '2026-10-22 22:35:47'),
(12, 'checkout', 'Hướng dẫn mua hàng trên website', 'Chủ đề: đặt hàng. Bạn chọn sản phẩm, thêm vào giỏ, đăng nhập rồi điền thông tin giao hàng để đặt hàng. Hiện cửa hàng hỗ trợ thanh toán khi nhận hàng hoặc chuyển khoản mô phỏng.', 1, '2026-10-22 22:35:47'),
(13, 'checkout', 'Cách thêm sản phẩm vào đơn hàng', 'Chủ đề: đặt hàng. Bạn chọn sản phẩm, thêm vào giỏ, đăng nhập rồi điền thông tin giao hàng để đặt hàng. Hiện cửa hàng hỗ trợ thanh toán khi nhận hàng hoặc chuyển khoản mô phỏng.', 1, '2026-10-22 22:35:47'),
(14, 'checkout', 'Tôi muốn tạo đơn mua hàng', 'Chủ đề: đặt hàng. Bạn chọn sản phẩm, thêm vào giỏ, đăng nhập rồi điền thông tin giao hàng để đặt hàng. Hiện cửa hàng hỗ trợ thanh toán khi nhận hàng hoặc chuyển khoản mô phỏng.', 1, '2026-10-22 22:35:47'),
(15, 'checkout', 'Các bước đặt hàng như thế nào?', 'Chủ đề: đặt hàng. Bạn chọn sản phẩm, thêm vào giỏ, đăng nhập rồi điền thông tin giao hàng để đặt hàng. Hiện cửa hàng hỗ trợ thanh toán khi nhận hàng hoặc chuyển khoản mô phỏng.', 1, '2026-10-22 22:35:47'),
(16, 'order', 'Kiểm tra đơn hàng ở đâu?', 'Chủ đề: đơn hàng. Đăng nhập tài khoản, mở mục đơn hàng để xem trạng thái hoặc hủy đơn khi đơn vẫn đang chờ xác nhận.', 1, '2026-10-22 22:35:47'),
(17, 'order', 'Xem trạng thái đơn hàng thế nào?', 'Chủ đề: đơn hàng. Đăng nhập tài khoản, mở mục đơn hàng để xem trạng thái hoặc hủy đơn khi đơn vẫn đang chờ xác nhận.', 1, '2026-10-22 22:35:47'),
(18, 'order', 'Tôi muốn xem lịch sử mua hàng', 'Chủ đề: đơn hàng. Đăng nhập tài khoản, mở mục đơn hàng để xem trạng thái hoặc hủy đơn khi đơn vẫn đang chờ xác nhận.', 1, '2026-10-22 22:35:47'),
(19, 'order', 'Có thể hủy đơn hàng không?', 'Chủ đề: đơn hàng. Đăng nhập tài khoản, mở mục đơn hàng để xem trạng thái hoặc hủy đơn khi đơn vẫn đang chờ xác nhận.', 1, '2026-10-22 22:35:47'),
(20, 'order', 'Đơn hàng của tôi đang ở trạng thái nào?', 'Chủ đề: đơn hàng. Đăng nhập tài khoản, mở mục đơn hàng để xem trạng thái hoặc hủy đơn khi đơn vẫn đang chờ xác nhận.', 1, '2026-10-22 22:35:47'),
(21, 'delivery', 'Shop giao hàng như thế nào?', 'Chủ đề: giao hàng. Bạn có thể nhập địa chỉ giao hàng khi đặt đơn. Để kiểm tra phí hoặc tiến độ giao hàng cụ thể, hãy gửi mã đơn hoặc chọn “Gặp nhân viên”.', 1, '2026-10-22 22:35:47'),
(22, 'delivery', 'Phí vận chuyển là bao nhiêu?', 'Chủ đề: giao hàng. Bạn có thể nhập địa chỉ giao hàng khi đặt đơn. Để kiểm tra phí hoặc tiến độ giao hàng cụ thể, hãy gửi mã đơn hoặc chọn “Gặp nhân viên”.', 1, '2026-10-22 22:35:47'),
