('75854AAB59', 'Sạc Sony CP-AD2', 'Phụ kiện', 'Sony', 'Mua ngay Sạc Sony CP-AD2 chính hãng, giá tốt, bảo hành tại Hệ thống CellphoneS.com.vn ✓Giá rẻ hơn ✓1 đổi 1 trong 12 tháng ✓Giao hàng miễn phí', 237000, 112, 4304, 'sac-sony-cp-ad2-75854AAB59', 'published', 290000, 'https://cellphones.com.vn/sac-sony-cp-ad2.html', '{\"manufacturer\":\"Hãng khác\",\"raw\":\"Cổng giao tiếp: USB | Công suất: 2A | Tính năng khác: Cung cấp dòng điện sạc thiết bị | Hãng sản xuất: Hãng khác\"}', NULL, NULL, NULL, 0),
('75861A6C9D', 'TECNO POVA 6 8GB 256GB - Cũ đẹp', 'Điện thoại', 'TECNO', 'Mua ngay Pova 6 cũ giá rẻ - Nguồn gốc rõ ràng, bảo hành 6-12 tháng, đổi mới 30 ngày, luôn xuất bán đầy đủ VAT.', 2748000, 144, 1362, 'tecno-pova-6-8gb-256gb-cu-dep-75861A6C9D', 'draft', 3090000, 'https://cellphones.com.vn/tecno-pova-6-8gb-256gb-cu-dep.html', '{\"cpu\":\"MediaTek G99 Ultimate | 2*A76 up to 2.2Ghz 6*A55 up to 2.0Ghz\",\"ram\":\"8 GB\",\"storage\":\"256 GB\",\"display\":\"6.78 inches | AMOLED | 1080 x 2436 pixels\",\"battery\":\"6.000 mAh\",\"operating_system\":\"Android 14\",\"dimensions\":\"Kích thước màn hình: 6.78 inches\",\"raw\":\"Kích thước màn hình: 6.78 inches | Công nghệ màn hình: AMOLED | Camera sau: 108M + AI | Camera trước: Camera trước 32MP với đèn flash kép | Chipset: MediaTek G99 Ultimate | Công nghệ NFC: Có | Dung lượng RAM: 8 GB | Bộ nhớ trong: 256 GB | Pin: 6.000 mAh | Thẻ SIM: 2 Nano-SIM | Hệ điều hành: Android 14 | Độ phân giải màn hình: 1080 x 2436 pixels | Loại CPU: 2*A76 up to 2.2Ghz 6*A55 up to 2.0Ghz\"}', NULL, NULL, NULL, 1),
('758C93EAD1', 'OPPO A57 3GB 64GB - Cũ đẹp', 'Điện thoại', 'OPPO', 'Mua Oppo A57 cũ giá rẻ - Nguồn gốc rõ ràng, bảo hành 6-12 tháng, đổi mới 30 ngày, luôn xuất bán đầy đủ VAT.', 1417000, 89, 1213, 'oppo-a57-3gb-64gb-cu-dep-758C93EAD1', 'draft', 1590000, 'https://cellphones.com.vn/oppo-a57-3gb-64gb-cu-dep.html', '{\"cpu\":\"MediaTek Helio G35 | 2x2,4 GHz Cortex-A76 & 6x2,0 GHz Cortex-A55\",\"ram\":\"3 GB\",\"storage\":\"64 GB\",\"graphics\":\"IMG GE8320 @ 680 MHz\",\"display\":\"6.56 inches | IPS LCD | 720 x 1612 (HD+) | 60 Hz, 16 triệu màu, 269 PPI\",\"battery\":\"Li-Po 5000 mAh\",\"operating_system\":\"ColorOS 12.1, nền tảng Android 12\",\"dimensions\":\"Kích thước màn hình: 6.56 inches\",\"raw\":\"Hệ điều hành khi ra mắt: ColorOS 12.1, nền tảng Android 12 | Chipset: MediaTek Helio G35 | Dung lượng RAM: 3 GB | Bộ nhớ trong: 64 GB | Loại CPU: 2x2,4 GHz Cortex-A76 & 6x2,0 GHz Cortex-A55 | GPU: IMG GE8320 @ 680 MHz | Kích thước màn hình: 6.56 inches | Công nghệ màn hình: IPS LCD | Độ phân giải màn hình: 720 x 1612 (HD+) | Tính năng màn hình: 60 Hz, 16 triệu màu, 269 PPI | Camera sau: Camera gốc rộng: 13 MP, f\\/2.2, AF: Camera cảm biến độ sâu: 2 MP, f\\/2.4 | Camera trước: Camera gốc rộng: 8 MP, f\\/2.0 | Pin: Li-Po 5000 mAh | Hỗ trợ mạng: 4G | Thẻ SIM: 2 SIM (Nano-SIM) | Công nghệ NFC: Không\"}', NULL, NULL, NULL, 1),
('75A157473D', 'Đầu đĩa than JBL TT350 Classic', 'Khác', 'JBL', 'Mua DRS - Đầu quay đĩa than hiệu JBL TT350 Classic chính hãng - Giá tốt, bảo hành uy tín, giao hàng tận nơi toàn quốc. Mua ngay JBL TT350 Classic tại đây.', 15851000, 146, 2149, 'dau-dia-than-jbl-tt350-75A157473D', 'draft', 18900000, 'https://cellphones.com.vn/dau-dia-than-jbl-tt350.html', '{\"manufacturer\":\"JBL\",\"dimensions\":\"5 kg | 155 x 449 x 395 mm (H x W x D)\",\"raw\":\"Hãng sản xuất: JBL | Trọng lượng: 5 kg | Kích thước: 155 x 449 x 395 mm (H x W x D) | Kết nối: 1 x Stereo (RCA) | Tốc độ quay: 33 RPM \\/ 45 RPM | Loại kim: Audio Technica VM95E\"}', NULL, NULL, NULL, 0),
('75C0850DA7', 'Màn hình LG UltraFine 27U730B-B 27 inch', 'Màn hình', 'LG', 'Mua Màn hình LG UltraFine 27U730B-B 27 inch chính hãng - Giá rẻ, đảm bảo chất lượng, độ bền cao, hỗ trợ trả góp 0%, giao hàng miễn phí toàn quốc.', 7466000, 30, 3311, 'man-hinh-lg-ultrafine-27u730b-b-27-inch-75C0850DA7', 'published', 8590000, 'https://cellphones.com.vn/man-hinh-lg-ultrafine-27u730b-b-27-inch.html', '{\"display\":\"IPS | 16:9 | 60 Hz | 3840 x 2160 pixxels\",\"dimensions\":\"27 inches | Có chân đế: 61.5 × 47.8 × 22.1 cm: Không chân đế : 61.5 × 36.3 × 4.6 cm | Có chân đế: 6.1 kg: Không chân đế: 5.0 kg\",\"raw\":\"Kích thước thực tế (bao gồm viền): 27 inches | Tấm nền: IPS | Tỉ lệ màn hình: 16:9 | Tần số quét: 60 Hz | Thời gian phản hồi: 5ms | Treo tường: 100 x 100 mm | Cổng kết nối: 1x HDMI: 1x DisplayPort 1.4: 1x cổng tai nghe 3.5mm (3-pole, chỉ xuất âm thanh): 1 x USB-C PD 65W | Kích thước: Có chân đế: 61.5 × 47.8 × 22.1 cm: Không chân đế : 61.5 × 36.3 × 4.6 cm | Trọng lượng: Có chân đế: 6.1 kg: Không chân đế: 5.0 kg | Độ phân giải màn hình: 3840 x 2160 pixxels\"}', NULL, NULL, NULL, 0),
('760991EA42', 'Túi chống sốc có dây đeo Tomtoc (USA) Upgrade Version Defender A42 16 inch A42F2D2', 'Phụ kiện laptop', 'Khác', 'Mua Túi chống sốc có dây đeo Tomtoc (USA) Upgrade Version Defender A42 16 inch A42F2D2 chính hãng - Giá rẻ, đảm bảo chất lượng, độ bền cao, hỗ trợ giao hàng tận nơi toàn quốc.', 1022000, 126, 4397, 'tui-chong-soc-co-day-deo-tomtoc-usa-upgrade-version-defender-a42-16-inch-universal-a42d3d2-760991EA42', 'published', 1161000, 'https://cellphones.com.vn/tui-chong-soc-co-day-deo-tomtoc-usa-upgrade-version-defender-a42-16-inch-universal-a42d3d2.html', '{\"manufacturer\":\"Tomtoc\",\"dimensions\":\"16 inch\",\"raw\":\"Chất liệu: 400D Ripstop Polyester | Kích thước ngăn laptop: 16 inch | Tiện ích: Khóa kéo YKK Nhật Bản: Phần quai xách tay được bọc da PU êm ái: Đệm viền đàn hồi High-resilience: Công nghệ CornerArmor: Ngăn ẩn an toàn mặt sau | Hãng sản xuất: Tomtoc\"}', NULL, NULL, NULL, 0),
('7633D139AA', 'Máy lọc không khí Dyson Purifier Cool PC2 De-NOx TP12', 'Điện gia dụng', 'Dyson', 'Mua Máy lọc không khí Dyson Purifier Cool PC2 De-NOx TP12 chính hãng - Giá rẻ, đảm bảo chất lượng, độ bền cao, bảo hành uy tín, giao hàng tận nơi toàn quốc.', 18511000, 109, 850, 'may-loc-khong-khi-dyson-purifier-cool-pc2-de-nox-tp12-7633D139AA', 'published', 21990000, 'https://cellphones.com.vn/may-loc-khong-khi-dyson-purifier-cool-pc2-de-nox-tp12.html', '{\"graphics\":\"Chế độ Auto: Chế độ đêm\",\"manufacturer\":\"Dyson\",\"raw\":\"Diện tích sử dụng: ~ 27 m² | Hiệu quả lọc bụi: Hệ thống lọc 3 bước HEPA kín, loại bỏ 99,95% bụi mịn và khí độc: Khử mùi, formaldehyde liên tục | Màng lọc: HEPA + K-Carbon | Độ ồn: 61.5 dB | Công nghệ: Công nghệ Air Multiplier ™ | Chế độ hoạt động: Chế độ Auto: Chế độ đêm | Tiện ích: Dao động 350°: Theo dõi & điều khiển từ xa qua app MyDyson™: Hẹn giờ: Màn hình hiển thị chất lượng không khí | Hãng sản xuất: Dyson\"}', NULL, NULL, NULL, 0),
('7638168EB6', 'Tai nghe không dây LG Tone Free FP9 - Cũ', 'Âm thanh', 'LG', 'Mua Tai nghe LG Tone Free FP9 cũ chính hãng - Giá tốt, hỗ trợ trả góp, bảo hành uy tín, giao hàng tận nơi. Mua ngay LG Tone Free FP9 tại đây.', 2197000, 15, 287, 'tai-nghe-khong-day-lg-tone-free-fp9-cu-7638168EB6', 'draft', 2390000, 'https://cellphones.com.vn/tai-nghe-khong-day-lg-tone-free-fp9-cu.html', '{\"battery\":\"Case Sạc:390 mAh: Tai nghe:55 mAh | Tai nghe:6 giờ sử dụng: Case Sạc:18 giờ sử dụng: Sạc đầy tai nghe trong 1 giờ\",\"manufacturer\":\"LG\",\"raw\":\"Công nghệ âm thanh: Meridian: Xuyên âm: Xử lý Tín hiệu Số (DSP) | Micro: Mic đàm thoại | Phương thức điều khiển: Cảm ứng chạm | Tính năng khác: Sử dụng độc lập 1 bên tai: Tự động kết nối khi mở hộp: Tắt nhạc khi tháo tai: Diệt khuẩn nano UV | Pin: Case Sạc:390 mAh: Tai nghe:55 mAh | Dung lượng Pin: Tai nghe:6 giờ sử dụng: Case Sạc:18 giờ sử dụng: Sạc đầy tai nghe trong 1 giờ | Tính năng khác: Âm thanh MERIDIAN: Chế độ chống ồn | Hãng sản xuất: LG\"}', NULL, NULL, NULL, 1),
