('EE91711290', 'Cáp Baseus Cafule USB-A to Micro 1m', 'Âm thanh', 'Baseus', 'Mua Cáp Baseus Cafule USB-A to Micro 1m chính hãng, giá ưu đãi, bảo hành chính hãng, miễn phí giao hàng tận nơi.', 70000, 88, 91, 'cap-usb-a-to-micro-baseus-cafule-1m-EE91711290', 'published', 80000, 'https://cellphones.com.vn/cap-usb-a-to-micro-baseus-cafule-1m.html', '{\"manufacturer\":\"Baseus\",\"raw\":\"Sử dụng tối đa: 1 thiết bị | Đầu vào: USB-A | Đầu ra: Micro-USB | Tiện ích: Cáp vải dù: Đầu kim loại siêu bền: Truyền dữ liệu nhanh 480Mbps | Chiều dài dây: 1 mét | Hãng sản xuất: Baseus\"}', NULL, NULL, NULL, 0),
('EEB686CEDD', 'Máy in A3 HP LaserJet 5200', 'Máy in', 'HP', 'Mua Máy in A3 HP LaserJet 5200 chính hãng - Giá rẻ, đảm bảo chất lượng, độ bền cao, bảo hành uy tín, giao hàng tận nơi toàn quốc.', 0, 10, 3803, 'may-in-a3-hp-laserjet-5200-EEB686CEDD', 'draft', 0, 'https://cellphones.com.vn/may-in-a3-hp-laserjet-5200.html', '{\"raw\":\"Chức năng: In 2 mặt | Chất lượng in: 1200 x 1200 dpi | Tốc độ in: 35 trang\\/ phút | Công suất in: 35.000 trang\\/ tháng | Khay nạp giấy: 250 tờ\"}', NULL, NULL, NULL, 0),
('EEBFD142E5', 'Tai nghe Bluetooth True Wireless Baseus Bass EP10 NC', 'Âm thanh', 'Baseus', 'Mua Tai nghe Baseus Bass EP10 NC chính hãng - Giá tốt, bảo hành uy tín, giao hàng toàn quốc. Mua ngay Baseus Bass EP10 NC tại đây.', 311000, 57, 107, 'tai-nghe-bluetooth-true-wireless-baseus-bass-ep10-nc-EEBFD142E5', 'published', 350000, 'https://cellphones.com.vn/tai-nghe-bluetooth-true-wireless-baseus-bass-ep10-nc.html', '{\"battery\":\"Tai nghe: 7 giờ: Hộp sạc: 41 giờ (Tắt ANC)\",\"manufacturer\":\"Baseus\",\"raw\":\"Công nghệ âm thanh: Chống ồn môi trường ENC: Chống ồn chủ động ANC: 24 chế độ EQ | Micro: Có | Thời lượng sử dụng Pin: Tai nghe: 7 giờ: Hộp sạc: 41 giờ (Tắt ANC) | Phương thức điều khiển: Cảm ứng chạm: Điều khiển qua ứng dụng | Tính năng khác: Chống nước: IPX5 | Hãng sản xuất: Baseus\"}', NULL, NULL, NULL, 0),
('EEC3C8AD9E', 'HONOR X7e 8GB 128GB', 'Điện thoại', 'HONOR', 'Mua HONOR X7e 8GB 128GB chính hãng giá rẻ - Thu cũ đổi mới, bảo hành 12 tháng, đổi mới 30 ngày, trả góp 0%. Mua ngay HONOR X7e 8GB 128GB tại đây.', 0, 106, 1115, 'dien-thoai-honor-x7e-EEC3C8AD9E', 'draft', 0, 'https://cellphones.com.vn/dien-thoai-honor-x7e.html', '{\"cpu\":\"MediaTek Helio G81 Ultra | 8 nhân: 2xA75 2.0GHz + 6xA55 1.7GHz\",\"ram\":\"8 GB\",\"storage\":\"128 GB\",\"graphics\":\"ARM Mali-G52 MC2\",\"display\":\"6.61 inches | TFT LCD | 720 x 1604 (HD+) | Tần số quét 120 Hz: Độ sáng tối đa 1010 nits: 16.7 triệu màu: Công nghệ bảo vệ mắt Eye Comfort: Dynamic Dimming: Cảm ứng đa điểm tối đa 10 điểm chạm: Kính Aluminosilicate\",\"battery\":\"7500 mAh\",\"operating_system\":\"MagicOS 10.0 (dựa trên Android 16)\",\"dimensions\":\"Kích thước màn hình: 6.61 inches\",\"raw\":\"Hệ điều hành khi ra mắt: MagicOS 10.0 (dựa trên Android 16) | Chipset: MediaTek Helio G81 Ultra | Dung lượng RAM: 8 GB | Bộ nhớ trong: 128 GB | Loại CPU: 8 nhân: 2xA75 2.0GHz + 6xA55 1.7GHz | GPU: ARM Mali-G52 MC2 | Kích thước màn hình: 6.61 inches | Công nghệ màn hình: TFT LCD | Độ phân giải màn hình: 720 x 1604 (HD+) | Tính năng màn hình: Tần số quét 120 Hz: Độ sáng tối đa 1010 nits: 16.7 triệu màu: Công nghệ bảo vệ mắt Eye Comfort: Dynamic Dimming: Cảm ứng đa điểm tối đa 10 điểm chạm: Kính Aluminosilicate | Camera sau: 50 MP, f\\/1.8 | Camera trước: 5 MP, f\\/2.2 | Pin: 7500 mAh | Hỗ trợ mạng: 4G | Thẻ SIM: 2 Nano-SIM | Thời điểm ra mắt: 06\\/2026\"}', NULL, NULL, NULL, 0),
('EF179023FC', 'Infinix Hot 50 Pro Plus 8GB 256GB - Cũ Đẹp', 'Điện thoại', 'Infinix', 'Mua ngay điện thoại Infinix Hot 50 Pro Plus 8GB 256GB cũ giá rẻ - Nguồn gốc rõ ràng, bảo hành 6-12 tháng, đổi mới 30 ngày, luôn xuất bán đầy đủ VAT.', 2932000, 65, 1145, 'dien-thoai-infinix-hot-50-pro-plus-cu-dep-EF179023FC', 'draft', 3290000, 'https://cellphones.com.vn/dien-thoai-infinix-hot-50-pro-plus-cu-dep.html', '{\"cpu\":\"MediaTek Helio G100\",\"ram\":\"8 GB\",\"storage\":\"256 GB\",\"display\":\"6.78 inches | AMOLED | 1080 x 2436 pixels | 1080p 3D-Curved: 120Hz\",\"battery\":\"5,000 mAh\",\"operating_system\":\"Android 14\",\"dimensions\":\"Kích thước màn hình: 6.78 inches\",\"raw\":\"Kích thước màn hình: 6.78 inches | Công nghệ màn hình: AMOLED | Camera sau: 50MP + 2MP | Camera trước: 13MP | Chipset: MediaTek Helio G100 | Công nghệ NFC: Có | Dung lượng RAM: 8 GB | Bộ nhớ trong: 256 GB | Pin: 5,000 mAh | Thẻ SIM: 2 SIM (Nano-SIM) | Hệ điều hành: Android 14 | Độ phân giải màn hình: 1080 x 2436 pixels | Tính năng màn hình: 1080p 3D-Curved: 120Hz\"}', NULL, NULL, NULL, 1),
('EF19375497', 'Bàn phím cơ không dây Aula F108 Pro V2 Xám Đen Gradient', 'Chuột / Bàn phím', 'Khác', 'Mua Bàn phím cơ không dây Aula F108 Pro V2 Xám Đen Gradient chính hãng - Giá rẻ, đảm bảo chất lượng, độ bền cao, hỗ trợ giao hàng tận nơi toàn quốc.', 1414000, 141, 632, 'ban-phim-co-khong-day-aula-f108-pro-v2-xam-den-gradient-EF19375497', 'published', 1690000, 'https://cellphones.com.vn/ban-phim-co-khong-day-aula-f108-pro-v2-xam-den-gradient.html', '{\"manufacturer\":\"Aula\",\"raw\":\"Loại bàn phím: Full-size | Số phím: 108 phím | Tương thích: Windows, macOS, Android, iOS | Kết nối: 3 mode có dây Type-C & không dây 2.4G & BT | Khoảng cách kết nối (Độ dài dây): Lên đến 10m | Đèn LED: LED RGB 22 hiệu ứng ánh sáng | Thời gian dùng: Thời gian sử dụng sau khi sạc đầy pin: ≥31 giờ (LED mặc định)\\/ ≥600 giờ (tắt LED) | Hãng sản xuất: Aula\"}', NULL, NULL, NULL, 0),
('EF1960D390', 'Tai nghe Bluetooth chụp tai JBL Tune 780NC', 'Âm thanh', 'JBL', 'Mua Tai nghe JBL Tune 780NC chính hãng - Giá tốt, bảo hành uy tín, giao hàng tận nơi toàn quốc. Mua ngay JBL Tune 780NC tại đây.', 2878000, 77, 204, 'tai-nghe-bluetooth-chup-tai-jbl-tune-780nc-EF1960D390', 'published', 3350000, 'https://cellphones.com.vn/tai-nghe-bluetooth-chup-tai-jbl-tune-780nc.html', '{\"battery\":\"Tắt ANC: 76 giờ: Bật ANC: 50 giờ\",\"manufacturer\":\"JBL\",\"raw\":\"Công nghệ âm thanh: Âm thanh JBL Pure Bass: Spatial Sound | Micro: Có | Thời lượng sử dụng Pin: Tắt ANC: 76 giờ: Bật ANC: 50 giờ | Phương thức điều khiển: Nút bấm vật lý | Tính năng khác: Nhận biết giọng nói | Hãng sản xuất: JBL\"}', NULL, NULL, NULL, 0);
